import { useState, useContext, useEffect } from "react";
import { ComplaintContext } from "../context/ComplaintContext";
import { useLocation, useNavigate } from "react-router-dom";
import {
  MapContainer,
  TileLayer,
  Marker,
  useMapEvents
} from "react-leaflet";
import L from "leaflet";
import "../styles/global.css";

/* ⭐ Marker fix */
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon-2x.png",
  iconUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon.png",
  shadowUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-shadow.png"
});

function LocationPicker({ setPosition }) {
  useMapEvents({
    click(e) {
      setPosition(e.latlng);
    }
  });
  return null;
}

/* ⭐ distance calc */
const distance = (a,b)=>{
  if(!a||!b) return 0;
  const R=6371e3;
  const φ1=a.lat*Math.PI/180;
  const φ2=b.lat*Math.PI/180;
  const Δφ=(b.lat-a.lat)*Math.PI/180;
  const Δλ=(b.lng-a.lng)*Math.PI/180;

  const x=Math.sin(Δφ/2)**2 +
  Math.cos(φ1)*Math.cos(φ2)*
  Math.sin(Δλ/2)**2;

  return R*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));
}

function AddComplaint(){
  const { addComplaint, complaints } = useContext(ComplaintContext);
  const { state } = useLocation();
  const navigate = useNavigate();

  const department = state?.department || "General";
  const categories = [...(state?.categories || []), "Other"];

  const [useCurrent,setUseCurrent]=useState(true);
  const [position,setPosition]=useState(null);
  const [userPos,setUserPos]=useState(null);
  const [duplicate,setDuplicate]=useState(false);

  /* ⭐ GPS */
  useEffect(()=>{
    navigator.geolocation.getCurrentPosition((pos)=>{
      const p={lat:pos.coords.latitude,lng:pos.coords.longitude};
      setUserPos(p);
      if(useCurrent) setPosition(p);
    });
  },[useCurrent]);

  /* ⭐ duplicate detect */
  useEffect(()=>{
    if(!position) return;
    const found=complaints.some(c=>distance(c.coords,position)<50);
    setDuplicate(found);
  },[position,complaints]);

  const submit=()=>{
    addComplaint({
      department,
      coords:position,
      status:"Pending",
      timeline:["Submitted"]
    });
    navigate("/track");
  }

  return(
    <div className="complaint-page animated-bg">
      <div className="complaint-card">

        {/* ⭐ toggle */}
        <div className="toggle">
          <label>
            <input
              type="radio"
              checked={useCurrent}
              onChange={()=>setUseCurrent(true)}
            />
            Use current location
          </label>

          <label>
            <input
              type="radio"
              checked={!useCurrent}
              onChange={()=>setUseCurrent(false)}
            />
            Select different location
          </label>
        </div>

        {/* ⭐ MAP */}
        <MapContainer
          center={position||[17.385,78.486]}
          zoom={13}
          style={{height:"250px"}}
        >
          <TileLayer
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          />

          {position && (
            <Marker
              draggable
              position={position}
              eventHandlers={{
                dragend:(e)=>setPosition(e.target.getLatLng())
              }}
            />
          )}

          {!useCurrent && <LocationPicker setPosition={setPosition}/>}
        </MapContainer>

        {/* ⭐ distance info */}
        {userPos && position && (
          <p>
            Distance from you: {Math.round(distance(userPos,position))} meters
          </p>
        )}

        {/* ⭐ duplicate alert */}
        {duplicate && (
          <div className="duplicate">
            ⚠ Similar complaint exists nearby
          </div>
        )}

        <button onClick={submit}>Submit Complaint</button>
      </div>
    </div>
  )
}

export default AddComplaint;
